import {mountModel,hasInteractiveModel,esc} from './models.js';
import {checkNumeric} from './practice.js';
import {equationHTML,glossaryHTML,prerequisitesHTML} from './lesson-support.js';
import {mountSidebarLayout} from './layout.js';
import {trackForCourse,normalizeTrack,coursesForTrack,courseBadge} from './navigation.js';
import {parseSavedProgress,parseProgressImport,createProgressExport,saveProgress} from './progress.js';
const $=s=>document.querySelector(s),STORAGE='physicsquest.progress.v1';
const state={catalog:null,courses:new Map(),course:'foundations',track:'physics',courseByTrack:{physics:'foundations',quantum:'quantum1'},lesson:'units',phase:0,answers:{},notes:{},done:new Set(),save:false,storageAvailable:true};
let validIds=new Set(),fitSidebar=()=>{};
function storageMessage(t){$('#storageMessage').textContent=t;}
function persist(){if(!state.save)return false;try{if(!saveProgress(localStorage,state.done,true))throw Error('Unavailable');return true;}catch{state.storageAvailable=false;storageMessage('Saving is unavailable. Export a copy to keep your progress.');return false;}}
function loadProgress(){try{const d=parseSavedProgress(localStorage.getItem(STORAGE),validIds);state.save=d.enabled;state.done=new Set(d.completed);}catch{state.storageAvailable=false;}}
const completed=c=>c.lessons.filter(l=>state.done.has(c.id+'/'+l.id)).length;
const statusText=c=>c.status==='complete'?(c.id==='foundations'?'Introductory bridge ready':'Defined course available'):c.status==='partial'?'Course in development':'Planned · not yet available';
async function init(){try{state.catalog=await (await fetch('./content/catalog.json')).json();for(const meta of state.catalog.courses.filter(c=>c.status!=='planned')){const course=await (await fetch('./content/'+meta.id+'.json')).json();state.courses.set(meta.id,course);course.lessons.forEach(l=>validIds.add(course.id+'/'+l.id));}loadProgress();$('#courseSelect').addEventListener('change',e=>navigateCourse(e.target.value));$('#navToggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#navToggle').setAttribute('aria-expanded',open);});$('#progressButton').addEventListener('click',()=>{$('#progressPanel').hidden=!$('#progressPanel').hidden;});$('#saveProgress').checked=state.save;$('#saveProgress').addEventListener('change',e=>{state.save=e.target.checked;if(state.save){if(persist())storageMessage('Progress will be saved in this browser only.');}else{try{localStorage.removeItem(STORAGE);storageMessage('Saving is off. Session progress remains until you close or reload.');}catch{storageMessage('Saving is off for this session, but existing browser data could not be removed.');}}});$('#exportProgress').addEventListener('click',exportProgress);$('#importProgress').addEventListener('change',importProgress);$('#importProgressButton').addEventListener('click',()=>$('#importProgress').click());$('#resetProgress').addEventListener('click',()=>{if(!confirm('Clear PhysicsQuest completion marks in this browser? Your downloaded exports are not affected.'))return;state.done.clear();const saved=state.save?persist():true;render();storageMessage(saved?'Completion marks cleared.':'Session marks cleared, but browser storage could not be updated.');});window.addEventListener('hashchange',route);fitSidebar=mountSidebarLayout($('#sidebar'));route();}catch(e){$('#main').innerHTML='<h1>The studio could not load.</h1><p>Please reload the page. Your saved progress has not been changed.</p>';console.error(e);}}
function navigateCourse(id){const c=state.courses.get(id);location.hash=c?'learn/'+id+'/'+c.lessons[0].id:'course/'+id;}
function route(){const parts=location.hash.slice(1).split('/');if(parts[0]==='learn'&&state.courses.has(parts[1])){const c=state.courses.get(parts[1]);const l=c.lessons.find(x=>x.id===parts[2])??c.lessons[0];if(state.course!==c.id||state.lesson!==l.id)state.phase=0;state.course=c.id;state.lesson=l.id;state.track=trackForCourse(c.id);state.courseByTrack[state.track]=c.id;}else if(parts[0]==='course'&&state.catalog.courses.some(c=>c.id===parts[1])){state.course=parts[1];state.track=trackForCourse(state.course);state.courseByTrack[state.track]=state.course;}else if(parts[0]==='track'||parts[0]==='map'){state.track=normalizeTrack(parts[1]??state.track);state.course=state.courseByTrack[state.track];}render();if(window.innerWidth<721){$('#sidebar').classList.remove('open');$('#navToggle').setAttribute('aria-expanded','false');}window.scrollTo({top:0,behavior:'instant'});}
function render(){document.querySelectorAll('[data-track]').forEach(a=>{const active=a.dataset.track===state.track;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#mapLink').href='#map/'+state.track;renderSidebar();const type=location.hash.slice(1).split('/')[0];if(type==='map'||type==='track')renderMap();else if(type==='about')renderAbout();else if(type==='course'||!state.courses.has(state.course))renderCoursePlan();else renderLesson();fitSidebar();}
function renderSidebar(){$('#courseSelect').innerHTML=coursesForTrack(state.catalog.courses,state.track).map(c=>`<option value="${esc(c.id)}">${esc(c.title)}${c.status==='planned'?' — planned':''}</option>`).join('');const c=state.courses.get(state.course),meta=state.catalog.courses.find(c=>c.id===state.course);$('#courseSelect').value=state.course;$('#courseMeta').innerHTML=c?`<div class="progress-track" aria-hidden="true"><span style="width:${100*completed(c)/c.lessons.length}%"></span></div><p class="course-small">${completed(c)} of ${c.lessons.length} available lessons marked complete</p>`:`<p class="course-small">Planned · lessons not yet authored</p>`;$('#lessonNav').innerHTML=c?c.lessons.map((l,i)=>`${l.moduleId&&(i===0||c.lessons[i-1].moduleId!==l.moduleId)?`<div class="module-label">${esc(c.modules.find(m=>m.id===l.moduleId)?.title??l.moduleId)}</div>`:''}<a class="lesson-link ${l.id===state.lesson?'active':''} ${state.done.has(c.id+'/'+l.id)?'done':''}" href="#learn/${c.id}/${l.id}" ${l.id===state.lesson?'aria-current="page"':''}><span class="lesson-no" aria-hidden="true">${state.done.has(c.id+'/'+l.id)?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(l.title)}${state.done.has(c.id+'/'+l.id)?'<span class="sr-only"> — marked complete</span>':''}</span></a>`).join('')+`<a class="lesson-link" href="#course/${c.id}">View coverage & prerequisites</a>`:`<a class="lesson-link active" href="#course/${meta.id}">View course plan</a><a class="lesson-link" href="#map/${state.track}">All courses in this track</a>`;}
function renderLesson(){const c=state.courses.get(state.course),l=c.lessons.find(x=>x.id===state.lesson)??c.lessons[0],i=c.lessons.indexOf(l),key=c.id+'/'+l.id;document.title=l.title+' — PhysicsQuest';$('#main').innerHTML=`<div class="breadcrumb"><a href="#map/${state.track}">Learning path</a><span aria-hidden="true">/</span><a href="#course/${c.id}">${esc(c.title)}</a></div><div class="lesson-heading"><div><span class="pill">${esc(courseBadge(c))}</span><h1>${esc(l.title)}</h1></div><span class="lesson-count">${String(i+1).padStart(2,'0')} / ${String(c.lessons.length).padStart(2,'0')} available</span></div><div class="steps" aria-label="Lesson steps">${['Understand','Explore','Check','Apply'].map((p,j)=>`<button class="step ${state.phase===j?'active':''}" data-phase="${j}" ${state.phase===j?'aria-current="step"':''}><span>${j+1}</span>${p}</button>`).join('')}</div>${prerequisitesHTML(l,c.id,state.courses)}<div class="lesson-grid"><section class="reading" id="lessonReading" aria-label="${['Explanation','Exploration','Understanding check','Practical application'][state.phase]}"></section><aside class="visual-card" id="visual" aria-label="Lesson visual model"></aside></div>${glossaryHTML(l)}<div class="lesson-footer"><button id="markComplete" class="${state.done.has(key)?'marked':''}">${state.done.has(key)?'✓ Marked complete':'Mark complete'} <span class="sr-only">${esc(l.title)}</span></button><span class="subtle">Explore freely. Nothing is locked.</span><button id="continue" class="primary">${state.phase<3?['Explore the idea','Try a changed case','Use the idea'][state.phase]:i<c.lessons.length-1?'Next lesson →':'Back to course map →'}</button></div>`;
const reading=$('#lessonReading');if(state.phase===0){reading.innerHTML=`<p class="idea">${esc(l.idea)}</p>${l.body.map(p=>`<p>${esc(p)}</p>`).join('')}${equationHTML(l)}<details><summary>Worked example: ${esc(l.example.title)}</summary><ol>${l.example.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details>`;}else if(state.phase===1){reading.innerHTML=`<div class="smallheading">CHANGE ONE THING</div><h2>${esc(l.visual.title)}</h2><p>${esc(l.visual.caption)}</p><p>${hasInteractiveModel(l.visual)?'Before moving a control, predict what will change. Then compare the new result with your prediction.':'This is a visual summary, not a live simulation. Use the worked example to predict a changed case, then explain which assumption your prediction needs.'}</p>${equationHTML(l)}<div class="model-note"><strong>Where this model applies</strong><br>${esc(l.limits)}</div>`;}else if(state.phase===2){reading.innerHTML=`<div class="smallheading">A DIFFERENT CASE</div><h2>${esc(l.check.prompt)}</h2><p class="subtle">Choose a response. You can try again; no score or penalty.</p><div id="choices">${l.check.options.map((o,j)=>`<button class="choice" data-answer="${j}" aria-pressed="false">${esc(o)}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite"></div>`;const choose=j=>{state.answers[key]=j;document.querySelectorAll('.choice').forEach((b,k)=>{b.className='choice'+(k===j?' selected '+(j===l.check.answer?'correct':'wrong'):'');b.setAttribute('aria-pressed',k===j);});$('#feedback').className='feedback'+(j===l.check.answer?'':' wrong');$('#feedback').textContent=l.check.explanations[j];};document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>choose(+b.dataset.answer)));if(state.answers[key]!==undefined)choose(state.answers[key]);}else{reading.innerHTML=`<div class="smallheading">TAKE IT INTO THE WORLD</div><h2>${esc(l.apply.title)}</h2><p class="idea" style="font-size:20px">${esc(l.apply.text)}</p><label class="reasoning-label" for="myReasoning">My reasoning <span>(optional · this session only)</span></label><textarea id="myReasoning" rows="3" placeholder="Write a prediction or a short explanation…">${esc(state.notes[key]??'')}</textarea><button id="reveal" type="button" aria-expanded="false">Show one reasoned response</button><div id="applicationAnswer" class="apply-answer" hidden>${esc(l.apply.answer)}</div>${l.practice?practiceMarkup(l.practice):''}<div class="model-note"><strong>Keep the limits in view</strong><br>${esc(l.limits)}</div><p class="export-note" style="margin-top:22px">Completion is your choice. Mark the lesson when you can explain the idea in your own words.</p>`;$('#myReasoning').addEventListener('input',e=>{state.notes[key]=e.target.value;});$('#reveal').addEventListener('click',()=>{const open=$('#applicationAnswer').hidden;$('#applicationAnswer').hidden=!open;$('#reveal').setAttribute('aria-expanded',open);$('#reveal').textContent=open?'Hide response':'Show one reasoned response';});}mountModel($('#visual'),l.visual);if(state.phase===3&&l.practice)bindPractice(l.practice);document.querySelectorAll('[data-phase]').forEach(b=>b.addEventListener('click',()=>{state.phase=+b.dataset.phase;renderLesson();}));$('#markComplete').addEventListener('click',()=>{state.done.has(key)?state.done.delete(key):state.done.add(key);persist();renderSidebar();$('#markComplete').classList.toggle('marked',state.done.has(key));$('#markComplete').textContent=state.done.has(key)?'✓ Marked complete':'Mark complete';});$('#continue').addEventListener('click',()=>{if(state.phase<3){state.phase++;renderLesson();}else{state.phase=0;location.hash=i<c.lessons.length-1?`learn/${c.id}/${c.lessons[i+1].id}`:'map/'+state.track;}$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});});}
function renderMap(){const quantum=state.track==='quantum',courses=coursesForTrack(state.catalog.courses,state.track),available=courses.map(meta=>state.courses.get(meta.id)).filter(Boolean);document.title=(quantum?'Quantum Physics':'Physics')+' course map — PhysicsQuest';$('#main').innerHTML=`<div class="eyebrow">${quantum?'QUANTUM PHYSICS':'PHYSICS'} · YOUR LEARNING PATH</div><h1>${quantum?'From amplitudes to understanding.':'Start small. Go deeper.'}</h1><p class="map-intro">${quantum?'A rigorous path through quantum states, measurement and approximation. Mathematics and classical physics preparation are in the Physics tab.':'Build the tools, then explore motion, fields, waves, heat, light and the wider physical world. Quantum Physics has its own tab. Each course states its prerequisites, learning steps and model limits.'}</p><div class="notice"><strong>Current edition:</strong> ${available.length?available.map(c=>c.lessons.length+' '+c.title+' lessons').join(', ')+' are available.':'Quantum lessons are not yet published; the course plans below show the intended scope.'} Roadmap ${esc(state.catalog.roadmapVersion)} defines ${state.catalog.definedTarget} target micro-lessons across both tabs; ${state.catalog.courses.some(c=>c.status==='planned')?'planned targets are not delivered lessons.':'all defined lessons are available within the stated introductory scope.'} No compulsory locks.</div><div class="coursecards">${courses.map(c=>{const data=state.courses.get(c.id);return `<article class="coursecard"><div class="map-top"><span class="course-number">${c.symbol}</span><span class="pill ${c.status==='planned'?'planned':''}">${esc(statusText(c))}</span></div><h2>${esc(c.title)}</h2><p>${esc(c.subtitle)}</p><p class="small"><strong>Preparation:</strong> ${esc(c.prerequisites.join(' · '))}</p><p class="small">${data?data.lessons.length:0} of ${c.plannedLessons} target micro-lessons available</p><a href="#${data?'learn/'+c.id+'/'+data.lessons[0].id:'course/'+c.id}">${data?'Open course':'See the planned coverage'} →</a></article>`;}).join('')}</div>${quantum?'<section class="plan-banner"><h3>Build the prerequisites first</h3><p>Quantum models need complex numbers, calculus, linear algebra and wave physics. The prerequisite links guide preparation; there are no compulsory course locks.</p><a href="#track/physics">Open the Physics preparation path →</a></section>':''}<section class="plan-banner"><h3>Beyond the defined core</h3><p>${esc((quantum?['Quantum information','Advanced many-body and quantum field theory']:['Analytical mechanics and fluid dynamics','Plasma physics','Full general relativity','Advanced experimental methods']).join(' · '))}</p><p class="subtle">Optional future specializations, not yet authored. No finite app can cover every active research topic. The defined core is not a university qualification.</p></section>`;}
function renderCoursePlan(){const meta=state.catalog.courses.find(c=>c.id===state.course),data=state.courses.get(state.course);document.title=meta.title+' — PhysicsQuest';$('#main').innerHTML=`<div class="breadcrumb"><a href="#map/${state.track}">Learning path</a><span>/</span><span>Course coverage</span></div><span class="pill ${meta.status==='planned'?'planned':''}">${esc(statusText(meta))}</span><h1>${esc(meta.title)}</h1><p class="map-intro">${esc(meta.subtitle)}</p><div class="notice"><strong>Preparation:</strong> ${esc(meta.prerequisites.join(' · '))}</div><div class="plan-banner">${data?`${data.lessons.length} of ${meta.plannedLessons} target micro-lessons are available. ${meta.status==='complete'?'This course is available within its stated scope. Completion marks are self-reported, not proof of problem-solving mastery.':'The full course remains in development. Topic coverage below does not mean every topic has been taught to the required depth.'}`:'This is a coverage plan, not an available course. No lessons or exercises have been authored here yet.'}</div>${data?.statusNote?`<p class="course-scope-note">${esc(data.statusNote)}</p>`:''}<h2>What this course covers</h2><ol class="topics">${meta.coverage.map((t,i)=>`<li>${esc(t)}${meta.moduleTargets?` <small>${meta.moduleTargets[i]} ${meta.status==='complete'?'micro-lessons available':'target micro-lessons'}</small>`:''}${meta.plannedModules?.[i]?`<details class="planned-steps"><summary>${meta.status==='complete'?'See the course learning steps':'See the planned learning steps'}</summary><ol>${meta.plannedModules[i].objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ol></details>`:''}</li>`).join('')}</ol>${data?`<a class="primary" style="display:inline-block;text-decoration:none;margin-top:25px;border-radius:10px" href="#learn/${data.id}/${data.lessons[0].id}">Start the available lessons →</a>`:'<p style="margin-top:28px"><a href="#learn/foundations/units">Start with available Foundations →</a></p>'}`;}
function renderAbout(){document.title='About & sources — PhysicsQuest';$('#main').innerHTML=`<div class="about"><div class="eyebrow">INDEPENDENTLY AUTHORED</div><h1>Clear ideas. Honest limits.</h1><section><h2>How to use this studio</h2><p>Meet one idea, explore a model, test a different case and try a practical application. Use the contents at any time. Completion marks are optional; they do not certify mastery.</p><p>The available lessons and each course’s bounded learning map are listed on the course map. Foundations is an eight-lesson introductory bridge, not a substitute for calculus. Core courses need worked practice, changed cases and independent model selection—not merely familiarity with topic names. Mathematical prerequisites are shown explicitly.</p></section><section><h2>Progress and privacy</h2><p>Progress saving is off by default. If enabled, completion marks stay in this browser's local storage. There is no account-based progress sync, learning analytics or application backend. Clearing browser data can remove progress.</p><p>Use Progress settings to export a JSON backup or import one on another browser. Imported marks are merged with current marks. No file is uploaded. Your hosting provider may process standard server requests under its own policies.</p></section><section><h2>Original teaching, standard science</h2><p>The explanations, numerical examples, exercises, interface and diagrams were independently authored for PhysicsQuest. The links below were consulted to validate standard subject coverage, prerequisites and units—not to copy or adapt lecture prose, problem sets, figures or solutions.</p><p>Models are deliberately simplified and show their assumptions. Quantum mechanics concerns physical observations and predictions; it is not scientific proof of spiritual claims.</p><p>This independent learning project is not affiliated with or endorsed by MIT or any university, and does not award an equivalent credential.</p></section><section><h2>Source and licensing notes</h2><p>MIT OpenCourseWare generally uses CC BY-NC-SA 4.0, not the MIT software license. Rewording copied teaching material would not automatically remove its licensing obligations. No OCW course assets are bundled here.</p><p>The app has no third-party runtime code or external font/image dependencies. The original app code is MIT-licensed. Lesson text, exercises, worked examples and curriculum data are outside that license. Public source availability does not imply unrestricted reuse of teaching content.</p><ul>${state.catalog.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></li>`).join('')}<li><a href="https://ocw.mit.edu/pages/privacy-and-terms-of-use/" target="_blank" rel="noopener noreferrer">OCW terms and Creative Commons notice</a></li></ul><p class="subtle">Scope references and new field lessons reviewed 27–28 October 2026. Equations and topic names are standard scientific content; source-specific teaching expression is not reproduced.</p></section></div>`;}
function exportProgress(){const blob=new Blob([JSON.stringify(createProgressExport(state.done),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='physicsquest-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);storageMessage('Progress export downloaded. Keep it somewhere you can find it.');}
async function importProgress(e){try{const file=e.target.files?.[0];if(!file)return;if(file.size>1000000)throw Error('That file is too large.');const d=parseProgressImport(await file.text(),validIds);const ids=d.completed;ids.forEach(x=>state.done.add(x));const saved=persist();render();storageMessage(`Imported ${ids.length} recognized completion marks. ${saved?'Saved in this browser.':state.save?'Browser saving failed; export a backup.':'Saving is off; marks are kept for this session.'}`);}catch(err){storageMessage('Import not applied: '+err.message);}finally{e.target.value='';}}
init();

function practiceMarkup(p){return `<details class="numeric-practice"><summary>Practice the steps · ${p.parts.length} numerical ${p.parts.length===1?'part':'parts'}</summary><p>${esc(p.prompt)}</p><p class="subtle">Enter numbers only. For approximate answers, the feedback explains the accepted precision. Nothing is graded or locked.</p>${p.parts.map((part,i)=>`<div class="numeric-part"><label for="practice-${i}">${i+1}. ${esc(part.label)} <span>${esc(part.unit)}</span></label><div class="numeric-row"><input id="practice-${i}" type="number" step="any" inputmode="decimal" aria-describedby="practice-feedback-${i}"><button type="button" data-practice="${i}">Check</button></div><div id="practice-feedback-${i}" class="numeric-feedback" role="status"></div></div>`).join('')}<details><summary>Reasoning to compare with yours</summary><p>${esc(p.reasoning)}</p></details></details>`;}
function bindPractice(p){document.querySelectorAll('[data-practice]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.practice),part=p.parts[i],result=checkNumeric($('#practice-'+i).value,part.answer,part.tolerance),out=$('#practice-feedback-'+i);out.className='numeric-feedback '+(result.correct?'pass':'retry');out.textContent=!result.valid?result.message:result.correct?'That matches. '+part.feedback:'Not yet. '+part.feedback+(part.tolerance>=.0001?' An answer within '+part.tolerance+' '+part.unit+' is accepted.':'');}));}
